  "Run WSL only": "WSLだけを実行",
  "Use Tailscale Serve to expose this backend through a MagicDNS HTTPS URL.":
    "Tailscale Serveで、この接続先をMagicDNSのHTTPS URLから利用できるようにします。",
  "Start Tailscale to set up HTTPS access through MagicDNS.":
    "MagicDNS経由のHTTPS接続を設定するには、Tailscaleを起動してください。",
  "Enable Tailscale HTTPS": "TailscaleのHTTPSを有効にする",
  "Exposed on all interfaces.": "すべてのネットワークインターフェースで公開中です。",
  "Limited to this machine.": "このパソコンだけで利用できます。",
  "Remote access is already configured. Change network exposure where the server starts.":
    "リモートアクセスは設定済みです。ネットワークへの公開設定は、サーバーを起動する環境で変更してください。",
  "Only this machine can connect. Restart with a non-loopback host for remote pairing.":
    "このパソコンだけが接続できます。リモート接続には、ローカル専用以外のホストで再起動してください。",
  "Network exposure changes restart the backend and must be controlled where the server process is launched.":
    "公開設定を変更すると接続先を再起動します。サーバーを起動している環境から操作してください。",
  "Primary environment": "主環境",
  "More actions for this machine": "このパソコンのその他の操作",
  "Authorized clients": "許可済みクライアント",
  "Enable network access?": "ネットワークアクセスを有効にしますか？",
  "Disable network access?": "ネットワークアクセスを無効にしますか？",
  "Let your other devices connect to T3 Code over the network. Pair devices to give them access. T3 Code will restart.":
    "ネットワーク経由でほかのデバイスから接続できるようにします。接続設定でデバイスを許可してください。T3 Codeを再起動します。",
  "Devices connected over your local network will disconnect. Existing tunnels, such as T3 Connect or Tailscale HTTPS, keep working. T3 Code will restart.":
    "ローカルネットワーク経由のデバイスは切断されます。T3 ConnectやTailscale HTTPSのトンネル接続は継続します。T3 Codeを再起動します。",
  "Restart and enable": "再起動して有効にする",
  "Restart and disable": "再起動して無効にする",
  "Turn off WSL and switch back to Windows?": "WSLをオフにしてWindowsへ戻しますか？",
  "Disable WSL backend?": "WSLを無効にしますか？",
