const templateRules = templateTranslations
  // An unknown prefix cannot distinguish a UI label from authored text.
  .filter(({ parts }) => parts[0] !== "")
  .sort((left, right) => right.parts.join("").length - left.parts.join("").length);

const templateTexts = new Map(
  templateTranslations.map(({ parts, text }) => [JSON.stringify(parts), text]),
);

function fillTemplate(text: string, values: readonly string[]): string {
  return text.replace(/⟪(\d+)⟫/g, (_, index: string) => values[Number(index)] ?? "");
}

// Match each literal once, without backtracking through arbitrary message text.
function matchTemplate(value: string, parts: readonly string[]): string[] | null {
  const prefix = parts[0] ?? "";
  const suffix = parts.at(-1) ?? "";
  if (!value.startsWith(prefix) || !value.endsWith(suffix)) return null;
  let cursor = prefix.length;
  const end = value.length - suffix.length;
  const values: string[] = [];
  for (let index = 1; index < parts.length - 1; index++) {
    const part = parts[index] ?? "";
    const boundary = value.indexOf(part, cursor);
    if (boundary < cursor || boundary > end) return null;
    values.push(value.slice(cursor, boundary));
    cursor = boundary + part.length;
  }
  if (cursor > end) return null;
  values.push(value.slice(cursor, end));
  return values;
}

function translateText(value: string): string {
  // UI labels are short. Long messages and error details must stay untouched.
  if (value.length > 300) return value;
  const normalized = value.replace(/\s+/g, " ").trim();
  const direct = Object.hasOwn(translations, value)
    ? translations[value]
    : Object.hasOwn(translations, normalized)
      ? translations[normalized]
      : undefined;
  if (direct !== undefined) return direct;
  for (const rule of templateRules) {
    const match = matchTemplate(value, rule.parts);
    if (!match) continue;
    return fillTemplate(rule.text, match);
  }
  return value;
}

/** Translate fixed UI strings only. Authored values must bypass this function. */
export function ja<T>(value: T): T {
  return (typeof value === "string" ? translateText(value) : value) as T;
}

/** Translate a fixed UI template before inserting names, paths or free text. */
export function jaTemplate(parts: TemplateStringsArray, ...values: readonly unknown[]): string {
  const strings = values.map(String);
  const text = templateTexts.get(JSON.stringify(parts));
  if (text !== undefined) return fillTemplate(text, strings);
  return parts.reduce((result, part, index) => result + part + (strings[index] ?? ""), "");
}
